package com.villaserena.api.piso;
import java.util.*;
import java.math.BigDecimal;
import java.time.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import com.villaserena.api.auth.UsuarioActual;
import com.villaserena.api.comun.ApiException;
import tools.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
/** Registros operativos con control de versión y auditoría. No importa datos del navegador. */
@RestController
@RequestMapping("/api/v1/gestion")
@PreAuthorize("hasRole('ADMIN') or (hasRole('MANTENIMIENTO_LIMPIEZA') and @areas.mantenimiento())")
public class GestionOperativaController {
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final IncidenciaService incidencias;
 public GestionOperativaController(JdbcTemplate jdbc,ObjectMapper mapper,IncidenciaService incidencias){this.incidencias=incidencias;this.jdbc=jdbc;this.mapper=mapper;}
 private static final Set<String> TIPOS=Set.of("activos","preventivos","ordenes","insumos","compras","gastos","personal","correcciones");
 public record Guardar(@NotNull UUID id,@Min(0) long version,@NotNull Map<String,Object> datos){}
 private ApiException invalid(String s){return ApiException.datosInvalidos(s,List.of());}
 private void permiso(String tipo,boolean write){if(!TIPOS.contains(tipo))throw ApiException.noEncontrado();if(!"ADMIN".equals(UsuarioActual.rol())&&!Set.of("activos","preventivos","ordenes","insumos").contains(tipo))throw new ApiException(org.springframework.http.HttpStatus.FORBIDDEN,"ACCESO_DENEGADO","Esta operación requiere Administración.");if(write&&!"ADMIN".equals(UsuarioActual.rol())&&tipo.equals("insumos"))throw new ApiException(org.springframework.http.HttpStatus.FORBIDDEN,"ACCESO_DENEGADO","El inventario se administra desde Administración.");}
 @SuppressWarnings("unchecked") private Map<String,Object> leer(String s){return new LinkedHashMap<>(mapper.readValue(s,Map.class));}
 private Map<String,Object> fila(java.sql.ResultSet rs)throws java.sql.SQLException{var d=leer(rs.getString("datos"));d.put("id",rs.getString("id"));d.put("version",rs.getLong("version"));return d;}
 @GetMapping("/{tipo}") public List<Map<String,Object>> lista(@PathVariable String tipo){permiso(tipo,false);return jdbc.query("SELECT id,datos,version FROM gestion_registros WHERE tipo=? ORDER BY creado_en,id",(rs,n)->fila(rs),tipo);}
 @PostMapping("/{tipo}") @Transactional public Map<String,Object> guardar(@PathVariable String tipo,@Valid @RequestBody Guardar p){
  permiso(tipo,true);if(mapper.writeValueAsString(p.datos()).length()>64000)throw invalid("El registro es demasiado grande.");
  jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"gestion:"+tipo+":"+p.id());
  var rows=jdbc.queryForList("SELECT datos::text AS datos,creacion::text AS creacion,version FROM gestion_registros WHERE tipo=? AND id=? FOR UPDATE",tipo,p.id());Map<String,Object> old=rows.isEmpty()?null:leer((String)rows.getFirst().get("datos"));long version=rows.isEmpty()?0:((Number)rows.getFirst().get("version")).longValue();
  if(p.version()==0&&old!=null&&leer((String)rows.getFirst().get("creacion")).equals(p.datos())){old.put("id",p.id().toString());old.put("version",version);return old;}if(version!=p.version())throw ApiException.conflicto("VERSION_CAMBIADA","El registro cambió. Actualiza y revisa antes de guardar.");var d=new LinkedHashMap<>(p.datos());d.remove("id");d.remove("version");validar(tipo,d,old);
  String json=mapper.writeValueAsString(d),prior=old==null?null:mapper.writeValueAsString(old);
  if(old==null)jdbc.update("INSERT INTO gestion_registros(tipo,id,datos,creacion,creado_por) VALUES(?,?,?::jsonb,?::jsonb,?)",tipo,p.id(),json,mapper.writeValueAsString(p.datos()),UsuarioActual.id());else jdbc.update("UPDATE gestion_registros SET datos=?::jsonb,version=version+1,actualizado_en=now() WHERE tipo=? AND id=?",json,tipo,p.id());
  jdbc.update("INSERT INTO gestion_auditoria(tipo,registro_id,version,empleado_id,anterior,nuevo) VALUES(?,?,?,?,?::jsonb,?::jsonb)",tipo,p.id(),version+1,UsuarioActual.id(),prior,json);d.put("id",p.id().toString());d.put("version",version+1);return d;
 }
 private String text(Map<String,Object>d,String key,int max,boolean required){Object v=d.get(key);if(v==null&&!required)return "";if(!(v instanceof String s)||s.length()>max||(required&&s.isBlank()))throw invalid("Revisa "+key+".");return ((String)v).trim();}
 private BigDecimal numero(Map<String,Object>d,String key,boolean positive){try{var n=new BigDecimal(String.valueOf(d.get(key)));if(n.signum()<0||(positive&&n.signum()==0)||n.compareTo(new BigDecimal("99999999"))>0)throw invalid("Revisa "+key+".");return n;}catch(NumberFormatException e){throw invalid("Revisa "+key+".");}}
 private void fecha(Map<String,Object>d,String key){try{LocalDate.parse(text(d,key,10,true));}catch(java.time.format.DateTimeParseException e){throw invalid("Revisa la fecha "+key+".");}}
 private void opcion(Map<String,Object>d,String key,String...values){if(!Set.of(values).contains(d.get(key)))throw invalid("Revisa "+key+".");}
 private Map<String,Object> relacionado(String tipo,Object id){try{UUID key=UUID.fromString(String.valueOf(id));var r=jdbc.queryForList("SELECT datos::text AS datos FROM gestion_registros WHERE tipo=? AND id=? FOR UPDATE",tipo,key);if(r.isEmpty())throw invalid("Selecciona un registro existente de "+tipo+".");return leer((String)r.getFirst().get("datos"));}catch(IllegalArgumentException e){throw invalid("Selecciona un registro existente de "+tipo+".");}}
 private void validar(String tipo,Map<String,Object>d,Map<String,Object>old){switch(tipo){
  case "activos"->{text(d,"nombre",150,true);text(d,"categoria",100,true);text(d,"ubicacion",150,true);text(d,"marcaModelo",150,false);fecha(d,"instaladoEn");opcion(d,"estado","operativo","en-reparacion","fuera-servicio");if(d.containsKey("costo"))numero(d,"costo",false);}
  case "preventivos"->{text(d,"nombre",150,true);text(d,"ubicacion",150,true);text(d,"descripcion",2000,false);fecha(d,"proximaEjecucion");opcion(d,"frecuencia","semanal","mensual","trimestral","semestral","anual","otra");if("otra".equals(d.get("frecuencia"))){var dias=numero(d,"intervaloDias",true);if(dias.scale()>0||dias.compareTo(new BigDecimal("3660"))>0)throw invalid("El intervalo debe ser un número entero de días, máximo 3660.");}if(!(d.get("activa") instanceof Boolean))throw invalid("Indica si el plan está activo.");if(d.get("activoId")!=null&&!String.valueOf(d.get("activoId")).isBlank())relacionado("activos",d.get("activoId"));}
  case "ordenes"->orden(d,old);
  case "insumos"->{text(d,"nombre",150,true);text(d,"categoria",100,true);text(d,"unidad",30,true);numero(d,"stock",false);numero(d,"stockMinimo",false);numero(d,"costoUnitario",false);if(old!=null&&!numero(d,"stock",false).equals(numero(old,"stock",false)))throw invalid("Cambia el stock mediante un movimiento o compra.");}

  case "compras"->{if(old!=null)throw invalid("Las compras registradas no se sobrescriben.");text(d,"numeroFactura",100,true);text(d,"proveedor",150,true);fecha(d,"fecha");opcion(d,"estado","pagada","pendiente");var ins=relacionado("insumos",d.get("insumoId"));var cantidad=numero(d,"cantidad",true);var unit=numero(d,"costoUnitario",false);var bruto=cantidad.multiply(unit).setScale(2,java.math.RoundingMode.HALF_UP);boolean incluido=Boolean.TRUE.equals(d.get("ivaIncluido"));var subtotal=incluido?bruto.divide(new BigDecimal("1.12"),2,java.math.RoundingMode.HALF_UP):bruto;var impuesto=incluido?bruto.subtract(subtotal):subtotal.multiply(new BigDecimal("0.12")).setScale(2,java.math.RoundingMode.HALF_UP);d.put("subtotal",subtotal);d.put("impuesto",impuesto);d.put("total",subtotal.add(impuesto));ins.put("stock",numero(ins,"stock",false).add(cantidad));actualizarRelacionado("insumos",d.get("insumoId"),ins);}
  case "gastos"->{text(d,"concepto",300,true);text(d,"categoria",100,true);text(d,"comprobante",150,false);fecha(d,"fecha");numero(d,"monto",true);}
  case "personal"->{text(d,"nombre",150,true);text(d,"correo",150,true);text(d,"telefono",30,true);opcion(d,"asistencia","presente","ausente","pendiente","descanso");if(d.containsKey("empleadoId")){long id=Long.parseLong(String.valueOf(d.get("empleadoId")));if(jdbc.queryForObject("SELECT count(*) FROM empleados WHERE id=?",Integer.class,id)!=1)throw invalid("Empleado inexistente.");}}
  case "correcciones"->{text(d,"dato",100,true);text(d,"nuevo",300,true);text(d,"motivo",500,false);opcion(d,"estado","pendiente","aprobada","rechazada");}
  default->throw ApiException.noEncontrado();
 }}
 private void actualizarRelacionado(String tipo,Object id,Map<String,Object>d){var row=jdbc.queryForMap("SELECT datos::text AS datos,version FROM gestion_registros WHERE tipo=? AND id=?",tipo,UUID.fromString(String.valueOf(id)));long v=((Number)row.get("version")).longValue()+1;String json=mapper.writeValueAsString(d);jdbc.update("UPDATE gestion_registros SET datos=?::jsonb,version=?,actualizado_en=now() WHERE tipo=? AND id=?",json,v,tipo,UUID.fromString(String.valueOf(id)));jdbc.update("INSERT INTO gestion_auditoria(tipo,registro_id,version,empleado_id,anterior,nuevo) VALUES(?,?,?,?,?::jsonb,?::jsonb)",tipo,UUID.fromString(String.valueOf(id)),v,UsuarioActual.id(),row.get("datos"),json);}
 private void orden(Map<String,Object>d,Map<String,Object>old){
  text(d,"descripcion",2000,true);text(d,"ubicacion",150,true);text(d,"tipo",100,true);opcion(d,"prioridad","alta","media","baja");opcion(d,"origen","interna","preventivo","incidencia");opcion(d,"estado","abierta","asignada","en-proceso","resuelta","cerrada","cancelada");fecha(d,"fechaCompromiso");
  if(d.get("activoId")!=null)relacionado("activos",d.get("activoId"));if(d.get("tareaPreventivaId")!=null)relacionado("preventivos",d.get("tareaPreventivaId"));
  // Las averías que bloquean una habitación usan el servicio de incidencias, con sus reglas operativas.
  if(old==null&&Boolean.TRUE.equals(d.get("esHabitacion"))){var hab=jdbc.queryForList("SELECT id FROM habitaciones WHERE numero=? AND estado='ACTIVO'",Long.class,d.get("ubicacion"));if(hab.isEmpty())throw invalid("Selecciona una habitación del catálogo real.");if(d.get("incidenciaId")==null){var inc=incidencias.reportar(new com.villaserena.api.piso.dto.ReportarIncidenciaPeticion(hab.getFirst(),String.valueOf(d.get("descripcion")),Boolean.TRUE.equals(d.get("impideUso")),null),UsuarioActual.id());d.put("incidenciaId",inc.id().toString());}else{var inc=incidencias.detalle(Long.parseLong(d.get("incidenciaId").toString()));if(inc.estado().equals("RESUELTA")||inc.habitacion().id()!=hab.getFirst().longValue())throw invalid("La incidencia no corresponde a una avería activa de esa habitación.");if(inc.tecnicoACargo()!=null&&inc.tecnicoACargo().id()!=UsuarioActual.id())throw ApiException.conflicto("OTRO_TECNICO","La incidencia está a cargo de otro técnico.");d.put("impideUso",inc.impideUso());}}else if(Boolean.TRUE.equals(d.get("impideUso"))&&!Boolean.TRUE.equals(d.get("esHabitacion")))throw invalid("Para un equipo fuera de servicio, actualiza el estado de su activo.");
  String next=String.valueOf(d.get("estado"));if(old==null){if(!next.equals("abierta"))throw invalid("La orden comienza abierta.");d.put("codigo","OT-"+jdbc.queryForObject("SELECT nextval('gestion_orden_codigo')",Long.class));d.put("tecnicoId",null);d.put("creadaEn",Instant.now().toString());d.put("repuestos",List.of());d.put("historial",List.of(Map.of("estado","abierta","fechaHora",Instant.now().toString(),"responsable",UsuarioActual.rol())));return;}
  if(old.get("tecnicoId")!=null&&!"ADMIN".equals(UsuarioActual.rol())&&!String.valueOf(UsuarioActual.id()).equals(String.valueOf(old.get("tecnicoId"))))throw ApiException.conflicto("OTRO_TECNICO","La orden está a cargo de otro técnico.");for(String relation:List.of("activoId","tareaPreventivaId","incidenciaId"))if(!Objects.equals(old.get(relation),d.get(relation)))throw invalid("Las relaciones de la orden no se pueden sobrescribir.");if(!Objects.equals(d.get("fechaCompromiso"),old.get("fechaCompromiso")))text(d,"notaReprogramacion",500,true);String prev=String.valueOf(old.get("estado"));if(Set.of("cerrada","cancelada").contains(prev))throw ApiException.conflicto("ORDEN_CERRADA","La orden ya terminó.");
  if(!next.equals(prev)){if(next.equals("cancelada")){text(d,"motivoCancelacion",500,true);}else if(!Map.of("abierta","en-proceso","asignada","en-proceso","en-proceso","resuelta","resuelta","cerrada").getOrDefault(prev,"").equals(next))throw ApiException.conflicto("ESTADO_INVALIDO","Transición de orden no permitida.");
   if(next.equals("en-proceso")){d.put("tecnicoId",String.valueOf(UsuarioActual.id()));if(old.get("incidenciaId")!=null){long inc=Long.parseLong(old.get("incidenciaId").toString());if(incidencias.detalle(inc).estado().equals("REPORTADA"))incidencias.tomar(inc,UsuarioActual.id());}}else if(!next.equals("cancelada")&&!"ADMIN".equals(UsuarioActual.rol())&&!String.valueOf(UsuarioActual.id()).equals(String.valueOf(old.get("tecnicoId"))))throw ApiException.conflicto("OTRO_TECNICO","La orden está a cargo de otro técnico.");
   if(next.equals("resuelta")){text(d,"solucion",2000,true);numero(d,"minutosEmpleados",false);if(old.get("incidenciaId")!=null){long inc=Long.parseLong(old.get("incidenciaId").toString());if(!incidencias.detalle(inc).estado().equals("RESUELTA"))incidencias.resolver(inc,UsuarioActual.id(),String.valueOf(d.get("solucion")));}}if(next.equals("cerrada")){d.put("cerradaEn",Instant.now().toString());if(d.get("tareaPreventivaId")!=null){var plan=relacionado("preventivos",d.get("tareaPreventivaId"));var date=LocalDate.now(ZoneId.of("America/Guatemala"));plan.put("ultimaEjecucion",date.toString());String f=String.valueOf(plan.get("frecuencia"));plan.put("proximaEjecucion",(f.equals("otra")?date.plusDays(((Number)plan.get("intervaloDias")).longValue()):f.equals("semanal")?date.plusWeeks(1):date.plusMonths(Map.of("mensual",1L,"trimestral",3L,"semestral",6L,"anual",12L,"otra",1L).get(f))).toString());actualizarRelacionado("preventivos",d.get("tareaPreventivaId"),plan);}}
  }
  var history=new ArrayList<Map<String,Object>>();Object h=old.get("historial");if(h instanceof List<?> list)for(Object obj:list)if(obj instanceof Map<?,?> m){var item=new LinkedHashMap<String,Object>();m.forEach((k,v)->item.put(k.toString(),v));history.add(item);}history.add(Map.of("estado",next,"fechaHora",Instant.now().toString(),"responsable",UsuarioActual.rol(),"nota",String.valueOf(d.getOrDefault("solucion","Actualización operativa"))));d.put("historial",history);
  if(!Objects.equals(d.get("repuestos"),old.get("repuestos")))repuestos(d,old);
 }
 private Map<String,BigDecimal> cantidades(Object items){Map<String,BigDecimal> r=new HashMap<>();if(!(items instanceof List<?> list)||list.size()>50)throw invalid("Revisa los repuestos.");for(Object value:list){if(!(value instanceof Map<?,?> m))throw invalid("Repuesto inválido.");String id=String.valueOf(m.get("repuestoId"));BigDecimal n;try{n=new BigDecimal(String.valueOf(m.get("cantidad")));}catch(NumberFormatException e){throw invalid("Cantidad inválida.");}if(n.signum()<=0||n.compareTo(new BigDecimal("10000"))>0)throw invalid("Cantidad inválida.");r.merge(id,n,BigDecimal::add);}return r;}
 @SuppressWarnings("unchecked") private void repuestos(Map<String,Object>d,Map<String,Object>old){if(!"en-proceso".equals(old.get("estado")))throw invalid("Los repuestos se registran durante el trabajo en proceso.");if(!"ADMIN".equals(UsuarioActual.rol())&&!String.valueOf(UsuarioActual.id()).equals(String.valueOf(old.get("tecnicoId"))))throw ApiException.conflicto("OTRO_TECNICO","La orden está a cargo de otro técnico.");var before=cantidades(old.get("repuestos"));var after=cantidades(d.get("repuestos"));var ids=new TreeSet<String>();ids.addAll(before.keySet());ids.addAll(after.keySet());for(String id:ids){BigDecimal delta=after.getOrDefault(id,BigDecimal.ZERO).subtract(before.getOrDefault(id,BigDecimal.ZERO));if(id.startsWith("manual-"))continue;if(delta.signum()==0)continue;var stock=relacionado("insumos",id);var remaining=numero(stock,"stock",false).subtract(delta);if(remaining.signum()<0)throw ApiException.conflicto("STOCK_INSUFICIENTE","No hay repuestos suficientes.");stock.put("stock",remaining);actualizarRelacionado("insumos",id,stock);}
  for(Object value:(List<?>)d.get("repuestos")){Map<String,Object> part=(Map<String,Object>)value;String id=String.valueOf(part.get("repuestoId"));if(id.startsWith("manual-")){text(part,"nombre",150,true);numero(part,"costoUnitario",false);}else{var item=relacionado("insumos",id);part.put("nombre",item.get("nombre"));part.put("costoUnitario",item.get("costoUnitario"));}}
 }
}
